import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`law-firm-audit`,heroTitle:`Audit your law firm in minutes`,heroSubtitle:`Perplexity Computer audits your firm's site, local visibility, and consultation funnel, then shows exactly what to fix to attract more qualified matters.`,inputUrlCta:`Audit my firm`,inputUrlPlaceholder:`yourlawfirm.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this law firm. 1) Review the website for practice-area clarity, consultation flow, attorney credibility, and mobile conversion issues. 2) Audit the Google Business Profile, reviews, and local SEO setup. 3) Benchmark against top-ranked local firms for trust signals, intake friction, and positioning. 4) Recommend the highest-impact changes for consultation requests and case-quality improvement. 5) Deliver a prioritized action plan with rewritten copy and local growth recommendations.`,heroOverlaySteps:[`Reviewing your law firm site, practice pages, and consultation flow for conversion gaps`,`Auditing reviews, local visibility, and nearby firm positioning`,`Rewriting practice messaging and prioritizing the fixes most likely to drive consultations`,`Firm audit, intake improvements, and local SEO recommendations ready to use`],generatingSteps:[`Visiting {url} to review your law firm website, attorney pages, and consultation funnel`,`Designing an agent to benchmark local firms and visibility signals`,`Configuring copy rewrites, intake fixes, and local search recommendations`,`Setting up a prioritized action plan with consultation-growth opportunities`],featureSectionTitle:`From website friction to more qualified consultations`,featureCardTitles:[`Connects to your firm-growth stack`,`Fixes you can put live now`],featureCardDescriptions:[`Computer separates your firm audit into site review, intake analysis, local SEO, and competitor research, then routes each step to the right model.`,`Google Business Profile, Docs, Sheets, and planning tools can all feed one workflow so firm messaging and intake fixes stay coordinated.`,`Practice-page rewrites. Intake-flow improvements. Review-response guidance. Local SEO priorities. Computer gives you updates tied to more qualified leads.`],capabilitySectionTitle:`Your firm growth team, on autopilot`,capabilitySectionSubtitle:`Paste your firm URL, step away, and come back to a clearer plan to win more consultations.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review your practice pages, attorney credibility signals, CTA flow, and mobile experience to find the friction hurting lead quality.`},{title:`Local Visibility Review`,description:`Computer can assess your Google Business Profile, review strength, and local SEO setup to show where competing firms are outperforming you.`},{title:`Intake Messaging`,description:`Computer can rewrite your practice messaging, trust cues, and consultation CTAs so prospective clients understand why to contact you now.`},{title:`Connect Your Tools`,description:`Computer can organize findings across Google Business Profile, Docs, Sheets, and planning tools so your team can execute from one place.`},{title:`Remember Your Practice Areas`,description:`Computer can remember your focus areas, target matters, and preferred positioning so future audits start with the right context.`},{title:`Watch Lead Signals`,description:`Computer can revisit your digital presence over time, flag visibility or intake issues, and recommend the next update most likely to improve consultations.`}]});export{t as default};
